// Section selection handler
window.selectSection = function(sectionNum, isFull) {
    if (isFull) {
        showToast('This section is full. You can join the waitlist.', 'warning');
        return;
    }
    
    document.querySelectorAll('.section-option').forEach((el, idx) => {
        el.classList.toggle('selected', idx + 1 === sectionNum);
    });
};

function updateCourseCardSelection(courseCode) {
    document.querySelectorAll('.course-card').forEach(card => {
        if (card.dataset.code === courseCode) {
            card.classList.toggle('selected');
        }
    });
}

// Smart Scheduling System
const SchedulingEngine = {
    // Available time slots for scheduling
    timeSlots: [
        { id: 1, days: 'Su,T', dayNames: 'Sun/Tue', start: '08:00', end: '09:15', label: '8:00-9:15 AM' },
        { id: 2, days: 'Su,T', dayNames: 'Sun/Tue', start: '09:30', end: '10:45', label: '9:30-10:45 AM' },
        { id: 3, days: 'Su,T', dayNames: 'Sun/Tue', start: '11:00', end: '12:15', label: '11:00-12:15 PM' },
        { id: 4, days: 'Su,T', dayNames: 'Sun/Tue', start: '12:30', end: '13:45', label: '12:30-1:45 PM' },
        { id: 5, days: 'Su,T', dayNames: 'Sun/Tue', start: '14:00', end: '15:15', label: '2:00-3:15 PM' },
        { id: 6, days: 'M,W', dayNames: 'Mon/Wed', start: '08:00', end: '09:15', label: '8:00-9:15 AM' },
        { id: 7, days: 'M,W', dayNames: 'Mon/Wed', start: '09:30', end: '10:45', label: '9:30-10:45 AM' },
        { id: 8, days: 'M,W', dayNames: 'Mon/Wed', start: '11:00', end: '12:15', label: '11:00-12:15 PM' },
        { id: 9, days: 'M,W', dayNames: 'Mon/Wed', start: '12:30', end: '13:45', label: '12:30-1:45 PM' },
        { id: 10, days: 'M,W', dayNames: 'Mon/Wed', start: '14:00', end: '15:15', label: '2:00-3:15 PM' },
        { id: 11, days: 'Th', dayNames: 'Thursday', start: '09:00', end: '11:30', label: '9:00-11:30 AM' },
        { id: 12, days: 'Th', dayNames: 'Thursday', start: '12:00', end: '14:30', label: '12:00-2:30 PM' }
    ],
    
    // Track assigned schedules
    assignedSchedules: new Map(),
    instructorSchedules: new Map(),
    roomSchedules: new Map(),
    
    // Initialize scheduling for a student
    initForStudent(student) {
        this.assignedSchedules.clear();
        this.studentLevel = this.getStudentSemesterLevel(student);
        this.studentMajor = student.major;
        
        // Pre-populate instructor schedules from existing enrollments
        this.loadExistingSchedules();
    },
    
    // Get student's current semester level
    getStudentSemesterLevel(student) {
        const level = student.level?.toLowerCase() || '';
        if (level.includes('first')) return 2; // Going to semester 2
        if (level.includes('second')) return 4; // Going to semester 4
        if (level.includes('third')) return 6; // Going to semester 6
        if (level.includes('fourth')) return 8; // Going to semester 8
        return 6; // Default
    },
    
    // Load existing schedules to avoid conflicts
    loadExistingSchedules() {
        this.instructorSchedules.clear();
        this.roomSchedules.clear();
        
        // Create schedule map from existing enrollments
        AppState.enrollments.forEach(enrollment => {
            if (enrollment.time && enrollment.instructor) {
                const instructor = enrollment.instructor;
                if (!this.instructorSchedules.has(instructor)) {
                    this.instructorSchedules.set(instructor, []);
                }
                this.instructorSchedules.get(instructor).push(enrollment.time);
            }
        });
    },
    
    // Find best time slot for a course
    findBestTimeSlot(course, existingSelections) {
        // Get instructor for this course
        const courseEnrollment = AppState.enrollments.find(e => e.course_code === course.code);
        const instructor = courseEnrollment?.instructor || 'TBA';
        
        // Determine if course needs lab (CS courses typically need labs)
        const needsLab = course.code.startsWith('CSIT') || course.code.startsWith('CST');
        
        // Get available rooms
        const rooms = needsLab ? 
            AppState.rooms.filter(r => r.type === 'lab') :
            AppState.rooms.filter(r => r.type === 'classroom');
        
        // Find slots that don't conflict
        const availableSlots = this.timeSlots.filter(slot => {
            // Check if slot conflicts with already selected courses
            for (const selected of existingSelections) {
                if (selected.assignedSlot && this.slotsOverlap(slot, selected.assignedSlot)) {
                    return false;
                }
            }
            
            // Check instructor availability
            if (instructor !== 'TBA') {
                const instructorSlots = this.instructorSchedules.get(instructor) || [];
                for (const existingTime of instructorSlots) {
                    if (this.timeStringOverlaps(slot, existingTime)) {
                        return false;
                    }
                }
            }
            
            return true;
        });
        
        if (availableSlots.length === 0) {
            // No available slots - return a conflict indicator
            return {
                slot: this.timeSlots[0],
                room: rooms[0] || AppState.rooms[0],
                hasConflict: true,
                conflictReason: 'No available time slots without conflicts'
            };
        }
        
        // Prefer morning slots for core courses, afternoon for electives
        const preferredSlots = course.type === 'Major' ? 
            availableSlots.filter(s => parseInt(s.start) < 12) :
            availableSlots.filter(s => parseInt(s.start) >= 12);
        
        const selectedSlot = preferredSlots.length > 0 ? 
            preferredSlots[0] : 
            availableSlots[0];
        
        // Assign room based on course code for consistency
        const roomIndex = (course.code.charCodeAt(4) + course.code.charCodeAt(5)) % rooms.length;
        const room = rooms[roomIndex] || AppState.rooms[0];
        
        return {
            slot: selectedSlot,
            room: room,
            hasConflict: false,
            instructor: instructor
        };
    },
    
    // Check if two slots overlap
    slotsOverlap(slot1, slot2) {
        // Same days?
        const days1 = slot1.days.split(',');
        const days2 = slot2.days.split(',');
        const sameDays = days1.some(d => days2.includes(d));
        
        if (!sameDays) return false;
        
        // Check time overlap
        const start1 = this.timeToMinutes(slot1.start);
        const end1 = this.timeToMinutes(slot1.end);
        const start2 = this.timeToMinutes(slot2.start);
        const end2 = this.timeToMinutes(slot2.end);
        
        return !(end1 <= start2 || end2 <= start1);
    },
    
    // Check if slot overlaps with existing time string like "M,W(09:00 - 10:15)"
    timeStringOverlaps(slot, timeString) {
        const match = timeString.match(/([A-Za-z,]+)\((\d{2}:\d{2})\s*-\s*(\d{2}:\d{2})\)/);
        if (!match) return false;
        
        const days = match[1].split(',');
        const slotDays = slot.days.split(',');
        const sameDays = days.some(d => slotDays.includes(d));
        
        if (!sameDays) return false;
        
        const start1 = this.timeToMinutes(slot.start);
        const end1 = this.timeToMinutes(slot.end);
        const start2 = this.timeToMinutes(match[2]);
        const end2 = this.timeToMinutes(match[3]);
        
        return !(end1 <= start2 || end2 <= start1);
    },
    
    timeToMinutes(time) {
        const [hours, mins] = time.split(':').map(Number);
        return hours * 60 + mins;
    },
    
    // Generate section number based on scheduling
    getSectionNumber(course, slot) {
        // Morning slots get section 001, afternoon get 002
        return parseInt(slot.start) < 12 ? '001' : '002';
    }
};

function updateSelectedCoursesList() {
    const container = document.getElementById('selected-courses-list');
    const countEl = document.getElementById('selected-count');
    const totalCreditsEl = document.getElementById('total-selected-credits');
    const submitBtn = document.getElementById('submit-registration');
    
    if (!container) return;
    
    countEl.textContent = AppState.selectedCourses.length;
    
    const totalCredits = AppState.selectedCourses.reduce((sum, c) => sum + (parseInt(c.credits) || 3), 0);
    totalCreditsEl.textContent = totalCredits;
    
    submitBtn.disabled = AppState.selectedCourses.length === 0;
    
    if (AppState.selectedCourses.length === 0) {
        container.innerHTML = '<div class="empty-selection"><p>No courses selected</p></div>';
        return;
    }
    
    // Initialize scheduling engine for current student
    SchedulingEngine.initForStudent(AppState.currentUser);
    
    // Assign schedules to each selected course
    const scheduledCourses = [];
    let hasAnyConflict = false;
    
    AppState.selectedCourses.forEach(course => {
        const schedule = SchedulingEngine.findBestTimeSlot(course, scheduledCourses);
        
        course.assignedSlot = schedule.slot;
        course.assignedRoom = schedule.room;
        course.assignedSection = SchedulingEngine.getSectionNumber(course, schedule.slot);
        course.hasConflict = schedule.hasConflict;
        course.assignedInstructor = schedule.instructor;
        
        if (schedule.hasConflict) hasAnyConflict = true;
        
        scheduledCourses.push(course);
    });
    
    // Update conflict warning
    const warningEl = document.getElementById('conflict-warning');
    if (warningEl) {
        warningEl.style.display = hasAnyConflict ? 'flex' : 'none';
    }
    
    container.innerHTML = AppState.selectedCourses.map(course => {
        const conflictClass = course.hasConflict ? 'has-conflict' : '';
        const slot = course.assignedSlot;
        const room = course.assignedRoom;
        
        return `
            <div class="selected-course-item ${conflictClass}">
                <div class="selected-course-info">
                    <div class="selected-course-header">
                        <h4>${course.code}</h4>
                        ${course.hasConflict ? `
                            <span class="conflict-badge" title="Schedule conflict detected">
                                <svg viewBox="0 0 24 24" fill="currentColor" width="14" height="14">
                                    <path d="M12 2L1 21h22L12 2zm0 3.5L19.5 19h-15L12 5.5zM11 10v4h2v-4h-2zm0 6v2h2v-2h-2z"/>
                                </svg>
                            </span>
                        ` : ''}
                    </div>
                    <p>${course.title}</p>
                    <div class="selected-schedule-details">
                        <span class="schedule-section">Section ${course.assignedSection}</span>
                        <span class="schedule-credits">${course.credits || 3} Credits</span>
                    </div>
                    <div class="selected-time-details">
                        <div class="time-item">
                            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <circle cx="12" cy="12" r="10"/>
                                <polyline points="12 6 12 12 16 14"/>
                            </svg>
                            ${slot.dayNames} ${slot.label}
                        </div>
                        <div class="time-item">
                            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/>
                                <circle cx="12" cy="10" r="3"/>
                            </svg>
                            ${room.name || room.id}
                        </div>
                        <div class="time-item instructor">
                            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/>
                                <circle cx="12" cy="7" r="4"/>
                            </svg>
                            ${course.assignedInstructor || 'TBA'}
                        </div>
                    </div>
                </div>
                <button class="btn-remove-course" onclick="removeCourse('${course.code}')">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <polyline points="3 6 5 6 21 6"/>
                        <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/>
                    </svg>
                </button>
            </div>
        `;
    }).join('');
    
    // Update the preview timetable if exists
    updatePreviewTimetable();
}

// Update preview timetable with selected courses
function updatePreviewTimetable() {
    const container = document.getElementById('preview-timetable');
    if (!container || AppState.selectedCourses.length === 0) return;
    
    // This would generate a mini timetable preview
    // Implementation depends on UI requirements
}

window.removeCourse = function(courseCode) {
    const index = AppState.selectedCourses.findIndex(c => c.code === courseCode);
    if (index > -1) {
        AppState.selectedCourses.splice(index, 1);
        updateCourseCardSelection(courseCode);
        updateSelectedCoursesList();
    }
};

function checkScheduleConflicts() {
    // Now handled in updateSelectedCoursesList
    updateSelectedCoursesList();
}

function handleFilterChange(e) {
    document.querySelectorAll('.filter-btn').forEach(btn => btn.classList.remove('active'));
    e.target.classList.add('active');
    
    const filter = e.target.dataset.filter;
    filterCourses(filter);
}

function filterCourses(filter) {
    const studyPlanKey = getStudyPlanKey(AppState.currentUser.major);
    const studyPlan = AppState.studyPlans[studyPlanKey];
    if (!studyPlan) return;
    
    let filteredCourses = studyPlan.courses;
    
    if (filter !== 'all') {
        filteredCourses = studyPlan.courses.filter(course => {
            const type = determineCourseType(course);
            return type === filter;
        });
    }
    
    const container = document.getElementById('available-courses-list');
    renderCoursesList(filteredCourses, container);
}

function handleCourseSearch(e) {
    const query = e.target.value.toLowerCase();
    const studyPlanKey = getStudyPlanKey(AppState.currentUser.major);
    const studyPlan = AppState.studyPlans[studyPlanKey];
    if (!studyPlan) return;
    
    const filteredCourses = studyPlan.courses.filter(course => 
        course.code.toLowerCase().includes(query) || 
        course.title.toLowerCase().includes(query)
    );
    
    const container = document.getElementById('available-courses-list');
    renderCoursesList(filteredCourses, container);
}

function saveDraft() {
    showToast('Draft saved successfully', 'success');
}

function submitRegistration() {
    if (AppState.selectedCourses.length === 0) {
        showToast('Please select at least one course', 'error');
        return;
    }
    
    showToast(`Registration submitted: ${AppState.selectedCourses.length} courses`, 'success');
    AppState.selectedCourses = [];
    updateSelectedCoursesList();
}

