// ==================== SEMESTER DATA MANAGEMENT ====================
// Store semester-specific data variations
const SemesterData = {
    currentSemester: 'spring2026',
    
    // Historical data multipliers for different semesters
    semesterMultipliers: {
        'fall2026': { students: 1.15, gpa: 1.02, completion: 1.02, label: 'Fall 2026' },
        'spring2026': { students: 1.10, gpa: 1.01, completion: 1.01, label: 'Spring 2026' },
        'fall2025': { students: 1.05, gpa: 1.0, completion: 1.0, label: 'Fall 2025' },
        'spring2025': { students: 1.0, gpa: 1.0, completion: 1.0, label: 'Spring 2025' },
        'fall2024': { students: 0.92, gpa: 0.98, completion: 0.97, label: 'Fall 2024' },
        'spring2024': { students: 0.85, gpa: 0.96, completion: 0.95, label: 'Spring 2024' },
        'fall2023': { students: 0.78, gpa: 0.94, completion: 0.93, label: 'Fall 2023' },
        'spring2023': { students: 0.72, gpa: 0.92, completion: 0.91, label: 'Spring 2023' }
    },
    
    // Get semester-adjusted statistics
    getStatsForSemester(semester) {
        const mult = this.semesterMultipliers[semester] || this.semesterMultipliers['spring2026'];
        const baseStats = calculateRealAdminStats();
        
        // Adjust based on semester
        const adjustedStudents = Math.round(baseStats.totalStudents * mult.students);
        const adjustedGPA = baseStats.avgGPA * mult.gpa;
        const adjustedCompletion = baseStats.completionRate * mult.completion;
        
        // Calculate changes from previous semester
        const prevSemester = this.getPreviousSemester(semester);
        const prevMult = this.semesterMultipliers[prevSemester] || mult;
        
        return {
            ...baseStats,
            totalStudents: adjustedStudents,
            avgGPA: adjustedGPA,
            completionRate: adjustedCompletion,
            scheduleEfficiency: baseStats.scheduleEfficiency * mult.completion,
            enrollmentChange: ((mult.students / prevMult.students) - 1) * 100,
            gpaChange: (mult.gpa - prevMult.gpa) * baseStats.avgGPA,
            completionChange: ((mult.completion / prevMult.completion) - 1) * 100,
            efficiencyChange: ((mult.completion / prevMult.completion) - 1) * 100 * 2,
            semesterLabel: mult.label,
            // Filter students based on "enrollment date" simulation
            recentEnrollments: baseStats.recentEnrollments.slice(0, Math.round(8 * mult.students))
        };
    },
    
    getPreviousSemester(current) {
        const order = ['spring2023', 'fall2023', 'spring2024', 'fall2024', 'spring2025', 'fall2025', 'spring2026', 'fall2026'];
        const idx = order.indexOf(current);
        return idx > 0 ? order[idx - 1] : order[0];
    }
};

