// Export to PDF
function exportToPDF() {
    const semester = SemesterData.currentSemester;
    const semesterLabel = SemesterData.semesterMultipliers[semester]?.label || semester;
    
    showToast('Generating PDF report...', 'info');
    
    // Get current stats
    const stats = SemesterData.getStatsForSemester(semester);
    
    // Create PDF content
    const pdfContent = generatePDFReport(stats, semesterLabel);
    
    // Create a blob and download
    const blob = new Blob([pdfContent], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    
    // Open in new window for printing
    const printWindow = window.open(url, '_blank');
    printWindow.onload = function() {
        printWindow.document.title = `CCK_Admin_Report_${semester}`;
        setTimeout(() => {
            printWindow.print();
        }, 500);
    };
    
    showToast('PDF report generated! Print dialog opened.', 'success');
}

