function loadPredictions() {
    const container = document.getElementById('section-predictions');
    if (!container) return;
    
    // Check if prediction module is loaded
    if (typeof renderPredictionDashboard === 'function') {
        renderPredictionDashboard('section-predictions');
    } else {
        container.innerHTML = `
            <div style="padding: 40px; text-align: center;">
                <div class="spinner" style="width: 40px; height: 40px; margin: 0 auto 16px;"></div>
                <h2 style="font-size: 20px; font-weight: 600; color: #1F2937; margin-bottom: 8px;">Loading Prediction Module...</h2>
                <p style="color: #6B7280;">Please wait while historical data is loaded.</p>
            </div>
        `;
        
        // Try to load the module
        setTimeout(() => {
            if (typeof loadHistoricalGrades === 'function') {
                loadHistoricalGrades().then(() => {
                    if (typeof renderPredictionDashboard === 'function') {
                        renderPredictionDashboard('section-predictions');
                    }
                });
            }
        }, 500);
    }
}

